export type VaultSettings = {
  /** Schema version for future migrations */
  version: 'v1';
  /** Recycle bin retention period in days (default: 30, range: 1-365) */
  recycleBinRetentionDays: number;
  /** Delete behavior: 'bin' = soft delete to recycle bin, 'permanent' = immediate hard delete */
  deleteBehavior: 'bin' | 'permanent';
  /** Maximum number of past versions retained per file (default: 10, range: 0-100) */
  maxVersionsPerFile: number;
  /** Cooldown period for automatic version creation in minutes (default: 15, range: 0-1440) */

useVaultSettingsStore.getState().setSettings(vaultSettings);

// Update bin store retention from user settings
useBinStore.getState().setRetentionDays(vaultSettings.recycleBinRetentionDays);

// @cipherbox/api-client is configured in lib/api-config.ts at module load time.

const sdkClient = initSdkClient({
  apiUrl,
  getAccessToken,
  vaultKeypair: {
    publicKey: userKeypair.publicKey,
    privateKey: userKeypair.privateKey,
  },
