 61	      new Promise<VaultSettings>((resolve) =>
 62	        setTimeout(() => resolve({ ...DEFAULT_VAULT_SETTINGS }), LOAD_TIMEOUT_MS)
 63	      ),
 64	    ]);
 65	    return result;
 66	  } catch {
 67	    return { ...DEFAULT_VAULT_SETTINGS };
 68	  }
 69	}
 70	
 71	/**
 72	 * Save vault settings as an encrypted IPNS entry.
 73	 *
 74	 * Follows the exact BYO-IPFS config save pattern:
 75	 * 1. Serialize settings JSON
 76	 * 2. ECIES-encrypt with user's publicKey
 77	 * 3. Upload encrypted blob to IPFS
 78	 * 4. Derive IPNS keypair and resolve current sequence number
 79	 * 5. Publish updated IPNS record
 80	 *
 81	 * @param params.settings - Validated VaultSettings to save
 82	 * @param params.userPublicKey - User's secp256k1 public key
 83	 * @param params.userPrivateKey - User's secp256k1 private key
 84	 */
 85	export async function saveVaultSettings(params: {
 86	  settings: VaultSettings;
 87	  userPublicKey: Uint8Array;
 88	  userPrivateKey: Uint8Array;
 89	  teeKeys?: { currentEpoch: number; currentPublicKey: string } | null;
 90	}): Promise<void> {
 91	  const { settings, userPublicKey, userPrivateKey, teeKeys } = params;
 92	
 93	  // 1. Serialize and encrypt
 94	  const plaintext = new TextEncoder().encode(JSON.stringify(settings));
 95	  let encrypted: Uint8Array;
 96	  try {
 97	    encrypted = await wrapKey(plaintext, userPublicKey);
 98	  } finally {
 99	    clearBytes(plaintext);
100	  }
101	
102	  // 2. Upload to IPFS (addToIpfs expects a Blob)
103	  const blob = new Blob([encrypted as BlobPart]);
104	  const { cid } = await addToIpfs(blob);
105	
106	  // 3. Derive IPNS keypair
107	  const keypair = await deriveVaultSettingsIpnsKeypair(userPrivateKey);
108	
109	  // 4. Resolve current sequence number for monotonic increment
110	  let sequenceNumber = 0n;
111	  try {
112	    const resolved = await resolveIpnsRecord(keypair.ipnsName);
113	    if (resolved) {
114	      sequenceNumber = BigInt(resolved.sequenceNumber ?? 0) + 1n;
115	    }
116	  } catch {
117	    // First publish -- start from 0
118	  }
119	
120	  // 5. Wrap IPNS private key for TEE republishing (if available)
121	  let encryptedIpnsPrivateKey: string | undefined;
122	  let keyEpoch: number | undefined;
123	  if (teeKeys?.currentPublicKey) {
124	    const teePublicKey = hexToBytes(teeKeys.currentPublicKey);
125	    const wrappedKey = await wrapKey(keypair.privateKey, teePublicKey);
126	    encryptedIpnsPrivateKey = bytesToHex(wrappedKey);
127	    keyEpoch = teeKeys.currentEpoch;
128	  }
129	
130	  // 6. Create and publish IPNS record
131	  const result = await createAndPublishIpnsRecord({
132	    ipnsPrivateKey: keypair.privateKey,
133	    ipnsName: keypair.ipnsName,
134	    metadataCid: cid,
135	    sequenceNumber,
136	    encryptedIpnsPrivateKey,
137	    keyEpoch,
138	  });
139	
140	  if (!result.success) {
141	    throw new Error('Failed to publish vault settings to IPNS');
142	  }
143	}

