 1	/**
 2	 * @cipherbox/core - Vault Settings
 3	 *
 4	 * Default vault settings and validation for user-configurable parameters.
 5	 * Settings are stored as encrypted IPNS entries (zero-knowledge).
 6	 */
 7	
 8	import type { VaultSettings } from './types';
 9	
10	/**
11	 * Default vault settings matching current hardcoded behavior.
12	 * Used as fallback when no user settings exist or when loading fails.
13	 */
14	export const DEFAULT_VAULT_SETTINGS: VaultSettings = {
15	  version: 'v1',
16	  recycleBinRetentionDays: 30,
17	  deleteBehavior: 'bin',
18	  maxVersionsPerFile: 10,
19	  versionCooldownMinutes: 15,
20	};
21	
22	/**
23	 * Validate and sanitize vault settings input.
24	 *
25	 * Clamps out-of-range numeric values to valid bounds and returns
26	 * DEFAULT_VAULT_SETTINGS for corrupt or non-object input.
27	 *
28	 * @param input - Raw parsed settings (e.g., from JSON.parse of decrypted blob)
29	 * @returns Validated VaultSettings with all fields guaranteed valid
30	 */
31	export function validateVaultSettings(input: unknown): VaultSettings {
32	  if (!input || typeof input !== 'object') return { ...DEFAULT_VAULT_SETTINGS };
33	  const raw = input as Record<string, unknown>;
34	
35	  const recycleBinRetentionDays = clamp(toNumber(raw.recycleBinRetentionDays, 30), 0, 365);
36	  const deleteBehavior =
37	    raw.deleteBehavior === 'bin' || raw.deleteBehavior === 'permanent' ? raw.deleteBehavior : 'bin';
38	  const maxVersionsPerFile = clamp(toNumber(raw.maxVersionsPerFile, 10), 0, 100);
39	  const versionCooldownMinutes = clamp(toNumber(raw.versionCooldownMinutes, 15), 0, 1440);
40	
41	  return {
42	    version: 'v1',
43	    recycleBinRetentionDays,
44	    deleteBehavior,
45	    maxVersionsPerFile,
46	    versionCooldownMinutes,
47	  };
48	}
49	
50	function clamp(value: number, min: number, max: number): number {
51	  return Math.min(max, Math.max(min, Math.floor(value)));
52	}
53	
54	function toNumber(value: unknown, fallback: number): number {
55	  const n = Number(value);
56	  return Number.isFinite(n) ? n : fallback;
57	}

